import json
p='data/batches/M3.json';Q=json.load(open(p));D={int(q['id'].split('-')[-1]):q for q in Q}
def r(n,topic,stem,options,answer,explanation,wrong,section,fact,source=None):
 q=D[n];q.update(topic=topic,stem=stem,options=dict(zip('ABCD',options)),answer=list(answer),explanation=explanation,distractors=wrong);q['review']={'status':'draft','author':'core_features','reviewer':None,'notes':['替换跨模块同认知任务为已联网核实的不同目标，待独立复审。']}
 if source:q['sources']=[dict(url='https://cloud.tencent.com/document/product/1759/'+source[0],title=source[1],version=source[2],verifiedAt='2026-10-09')]
 q['sources'][0].update(section=section,fact=fact)
r(5,'可下载文档接口参数','使用文档录入接口导入可下载文件，关于FileUrl与CosUrl的配置，哪些判断正确？',['可用FileUrl传入可下载资源URL','两者应二选一','同时提供会合并下载两份文档','若两者都提供，只使用CosUrl'],'ABD','可下载文档可通过录入接口传FileUrl；它与CosUrl应二选一。文档明确同时提供时以CosUrl为准，不会合并两种地址内容。',{'C':'两个参数有选择与优先规则，并非批量文档列表。'},'可下载文档导入步骤','可下载文档通过FileUrl传URL，与CosUrl二选一，同时提供只使用CosUrl。',('112702','文档概述','2026-09-16'))
r(9,'批量网页导入约束','准备导入80个网页地址，逐条上传入口无法一次完成。符合官方限制的替代方式是？',['把80条地址填到一个URL字符串','整理为xlsx，按单文件最多500条及15MB限制批量上传','改成csv后使用批量网页上传','逐条上传一次可放500个URL，无须换入口'],'B','逐条上传最多20个网址；批量网页导入支持xlsx，单次一个文件、最多500条网址且不超过15MB。80条应按批量模板组织，并继续核对文件大小及网页可访问性。',{'A':'单个地址字段不是批量文件协议。','C':'该批量网页入口列明xlsx。','D':'500是批量文件条数上限，逐条入口为20。'},'网页文件导入步骤','逐条上传最多20个URL；批量仅xlsx，单次1文件，最多500条且不超过15MB。')
r(13,'问答来源与关联文档','维护人员想把人工录入的问答“来源类型”改成文档生成，同时关联一篇手册。哪个判断符合问答设置？',['关联手册就自动改写来源类型','来源按导入方式自动确定不可改；关联文档可另行选择','来源与关联文档都不可修改','只改来源标签文字就能改变导入方式记录'],'B','问答来源按导入方式默认匹配，不支持修改；关联文档是独立可配置项，可从文档库选择。不能把证据关联动作误作改写来源类型。',{'A':'关联文档与来源类型是不同设置。','C':'文档明确关联文档可自定义选择。','D':'标签或显示文字不能重写导入来源。'},'问答设置 > 问答来源、关联文档','来源依导入方式匹配且不能修改，关联文档可自定义选择。')
r(14,'问答审核中编辑限制','问答状态显示“审核中”，运营人员需要改写答案。按官方状态规则，哪个判断正确？',['可修改答案但相似问不可改','审核中不支持编辑，应待该状态结束后按结果处理','打开关联文档即可绕过问答编辑限制','审核中仅限制删除，编辑不受影响'],'B','审核中表示系统正在审核问答，该状态不支持编辑。应按最终结果继续修改处理，不能将导入完成后的编辑能力提前套用到审核阶段。',{'A':'限制针对该状态下问答编辑，并非只限制相似问。','C':'关联文档入口不改变问答审核状态。','D':'官方明确不支持编辑。'},'问答状态 > 审核中','审核中正在执行问答审核，不支持对该状态下问答编辑。')
r(16,'问答分类层级','现有问答分类从根到叶已达10层，管理员还想在最深层增加子类。按文档应如何规划？',['继续增加，分类层级无上限','调整分类结构，使层级不超过10层','只有文档分类受限，问答可以无限嵌套','改用相似问即可直接创建第11层分类'],'B','问答分类最多10层；第11层不符合限制。应合并或调整分类层级，相似问用于不同问法共享答案，不是新增分类层级的替代入口。',{'A':'与最多10层限制相反。','C':'问答操作也明确列出10层上限。','D':'相似问和分类是不同管理结构。'},'问答操作 > 问答分类','问答分类最多10层，支持重命名、删除、搜索和添加子类。')
r(128,'技能场景分类选择','在Skills广场寻找用于知识库运维和工作流创建的原生技能，应优先查看哪个场景分类？',['搜索与获取','通用办公','经营管理','ADP平台能力'],'D','ADP平台能力分类覆盖文档管理、语义检索、知识库运维、工作流及应用创建；搜索与获取侧重从多来源寻找信息，不能替代平台构建运维目标。',{'A':'侧重信息检索获取，未对应题设平台管理任务。','B':'侧重办公文档协同。','C':'侧重经营分析与运营。'},'Skills广场的分类体系','ADP平台能力分类含文档管理、知识库运维、工作流与应用创建。')
r(129,'OCR技能分类','需要将票据和表单图片中的文字与字段提取成可编辑数据，在Skills场景分类中最直接对应哪项？',['图像处理中的图片增强','音视频处理中的语音识别','文字识别','通用办公中的文档格式转换'],'C','文字识别分类基于OCR和多模态技术，将图片中的文字和结构化信息提取成可编辑数据，明确适用于票据、证件和表单。图像增强改善图像而非等同字段提取。',{'A':'图像增强不等于输出可编辑文字字段。','B':'语音识别输入对象不同。','D':'格式转换不等于识别图片中的文本结构。'},'Skills广场的分类体系','文字识别基于OCR及多模态提取图片文字与结构化信息，适用于票据证件表单。')
r(158,'触发受理与执行完成','事件触发Webhook的POST调用返回instance_id，应怎样解释该返回值？',['任务已完成且业务结果必定成功','已自动生成新的触发器配置','这是应用AppKey，可复用为鉴权','请求受理成功并标识本次执行，可继续查询其结果'],'D','文档将instance_id定义为受理成功后的执行实例ID，供后续查询处理情况。受理与业务执行完成不同，应继续核对状态与结果。',{'A':'受理成功不是执行成功保证。','B':'返回的是执行实例而非触发器定义。','C':'实例ID不是调用密钥。'},'新建事件触发 > 触发执行','POST受理成功返回instance_id，用于后续查询该次执行。')
r(159,'查询触发执行实例','已取得某次事件触发的instance_id，查询该次状态与结果应怎样请求？',['再次POST同一业务参数并认为是查询','向同一Webhook URL发送带instance_id查询参数和Bearer Token的GET','只GET应用体验链接并附实例ID','将instance_id替换Bearer Token发起POST'],'B','查询执行情况使用同一Webhook URL的GET请求，instance_id定位执行实例，Bearer Token完成鉴权。再次POST是触发新执行，不是查询。',{'A':'POST用于触发执行，可能重复启动任务。','C':'体验链接不是事件状态查询地址。','D':'实例标识不能替代鉴权令牌。'},'新建事件触发 > 查询执行情况','使用同一Webhook URL，GET查询参数instance_id且携带Bearer Token查询执行。')
r(160,'触发器不推送模式','触发器的任务结果推送渠道设置为“不推送”，其执行行为是哪项？',['任务不会调度，也不会产生执行记录','任务仍执行但强制发送默认企微群','只有手动对话才能启动，定时失效','正常调度执行，记录可在执行日志查看，不主动推送消息'],'D','不推送仅控制主动消息输出；任务仍正常调度，执行记录保留在执行日志。不能把推送渠道与执行开关混为一谈。',{'A':'不推送不等于停用执行。','B':'未配置主动推送目的地，不会强制发群。','C':'推送方式不会把定时任务改为仅手动。'},'新建触发器 > 任务结果推送渠道','不推送仍正常调度执行，无主动消息推送，记录在执行日志查看。')
r(161,'触发器立即运行','每日定时触发器当前已启用，管理员点击“立即运行”测试一次后，原调度计划会怎样？',['永久改为从当前时间每天执行','本次手工执行自动取消下一次计划','定时规则被删除，必须重新创建','原调度计划不受这次手工执行影响'],'D','管理触发器说明中，立即运行手动触发一次执行，不影响原有调度计划。测试执行与编辑时间规则是不同操作。',{'A':'没有重设调度起点的规则。','B':'文档未规定本次运行抵扣计划运行。','C':'立即运行不是删除或编辑规则。'},'管理触发器','立即运行手工触发一次，不影响原调度计划。')
r(162,'定时频率配置','关于定时触发器的执行频率设置，哪些配置方式符合文档？',['单次模式指定日期时间，仅执行一次','间隔模式可设置每10分钟执行一次','Cron模式只能选择每天，不能输入表达式','每周模式可选择多个星期几并指定时间'],'AD','定时规则支持每天、每周、间隔、单次和Cron。每周可选多个星期；间隔最小1小时；Cron支持标准表达式；单次只在指定日期时间执行。',{'B':'间隔模式最小1小时，不是10分钟。','C':'Cron模式支持输入标准表达式。'},'新建定时触发 > 执行频率','每周可多选星期，间隔最小1小时，单次指定日期时间，Cron输入表达式。')
r(163,'触发器管理操作','关于事件触发器的维护，哪些说法符合文档列明的行为？',['编辑用于修改触发器配置','删除事件触发器后原Webhook URL和Token立即失效','暂停与删除完全相同，都永久移除配置','查看最近执行可获失败原因与耗时'],'ABD','触发器支持编辑、启用/暂停、查看最近执行与删除。删除事件触发器使地址和Token立即失效；暂停是切换运行状态，不等于删除定义。',{'C':'暂停是运行状态切换，删除才移除触发器并使地址令牌失效。'},'管理触发器','编辑修改配置，启停切换运行状态，最近执行含结果原因耗时，删除事件触发器使URL及Token失效。')
r(165,'AgenticRAG重排模型取舍','AgenticRAG配置重排序模型时，团队更看重重排阶段响应速度，文档列明的轻量级选项是？',['youtu-rerank-llm','youtu-rerank','任意反思模型都等同重排序模型','无需区分，两选项仅名称不同'],'B','文档将youtu-rerank列为响应速度快的轻量级模型，将默认youtu-rerank-llm列为基于LLM、排序精度高的模型。题目只问列明定位，并不保证所有场景绝对快慢。',{'A':'该项文档定位为基于LLM、精度高。','C':'反思负责相关性与完整性评估，不等于重排模型选型。','D':'文档明确区分二者定位。'},'配置重排序模型','youtu-rerank为轻量级响应速度快；默认youtu-rerank-llm基于LLM、排序精度高。')
r(214,'变量赋值结果判断','工作流已用变量赋值节点更新全局变量，下游要确认赋值是否成功，哪些输出使用方式正确？',['读取bool类型isSuccess','把isSuccess当作更新后的业务变量全文','读取object类型Error了解报错','在该节点手动新增任意业务输出字段'],'AC','变量赋值节点默认输出isSuccess布尔值与Error对象，正常时Error为空，不支持手动新增。业务变量通过赋值更新，成功标志不等于业务值本身。',{'B':'isSuccess表示操作成功与否，不承载业务变量值。','D':'该节点不支持手工新增输出。'},'输出变量','变量赋值节点输出bool isSuccess和object Error，不支持手动新增。',('122550','变量赋值节点','2025-08-17'))
